package com.bank.idindex;

import java.util.*;
import java.util.logging.*;

public class DuplicateKeyDemo {
    private static final Logger log = Logger.getLogger("IdIndex");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Employee> staff = List.of(
            new Employee(101, "Rajesh"),
            new Employee(101, "Rajesh Kumar"),   // DUPLICATE id 101
            new Employee(102, "Priya"));
        IndexService service = new IndexService();

        try {
            service.indexNoMerge(staff);         // throws IllegalStateException
        } catch (IllegalStateException ex) {
            log.severe(() -> "no merge → " + ex.getMessage());
        }
        log.info(() -> "with merge → " + service.indexWithMerge(staff));
    }
}

// ─── Would be in model/Employee.java ───
class Employee {
    private final int id;
    private final String name;
    Employee(int id, String name) { this.id = id; this.name = name; }
    int getId() { return id; }
    String getName() { return name; }
}

// ─── Would be in service/IndexService.java ───
class IndexService {
    // two-arg toMap: duplicate key → IllegalStateException
    Map<Integer, String> indexNoMerge(List<Employee> staff) {
        return staff.stream()
            .collect(java.util.stream.Collectors.toMap(Employee::getId, Employee::getName));
    }

    // three-arg toMap: merge function resolves the collision
    Map<Integer, String> indexWithMerge(List<Employee> staff) {
        return staff.stream()
            .collect(java.util.stream.Collectors.toMap(
                Employee::getId, Employee::getName,
                (existing, replacement) -> existing));   // keep first on duplicate
    }
}
